const formatDate = (originalDate: Date) => {
	const when = new Date(originalDate)
	const now = new Date()
	const diffTime = Math.abs(Number(now) - Number(when))
	const finalTime = Number((diffTime / 1000 / 60).toFixed())
	if (finalTime < 60) {
		return `${finalTime}m`
	}
	if (finalTime >= 60 && finalTime <= 1440) {
		return `${Math.floor(finalTime / 60).toFixed()}h`
	}
	if (finalTime > 1440) {
		return `${(finalTime / 60 / 24).toFixed()}d`
	}
        return 'no date'
}


